import SiteShell from "@/components/site/SiteShell";
import type { Status } from "@/components/site/pages/StatusPage";

import statusJson from "../../site-data/vaerion-status.json";

/**
 * The single Next.js route (/) — the console.
 *
 * SiteShell (client) resolves 22 hash addresses (#/, #/docs/cli, …) with a
 * hydration-safe useSyncExternalStore router; the landing face of record
 * (the former single page.tsx, preserved section-for-section) is served at
 * "#/" via src/app/_components/landing.tsx.
 *
 * Status data: site-data/vaerion-status.json is generated by tools/status.ts
 * (the ONE measured source written by the verification gates). It is
 * imported at build time so the deployed bundle carries the measured
 * snapshot; StatusPage renders every claim defensively and says
 * "status data unavailable" when a measurement is absent.
 */
const status = statusJson as Status;

export default function Page() {
  return <SiteShell status={status} />;
}
